class CruftFreeStyledCell extends StatelessWidget {
  const CruftFreeStyledCell({super.key, required this.style, required this.child});

  final CruftFreeStyle style;
  final Widget child;

  @override
  Widget build(BuildContext context) => cruftfreeStyled(context, style, child);
}

/// One column: its heading, the cell it shows for a row, whether it holds a
