}

/// A table's `rowDetail { }`: which rows offer it ([offered]; `null`, every row), whether the
/// [isOpen] row (by its position among the rows shown) is open, what toggling one does, and
/// the detail it draws for a row.
class CruftFreeRowDetail<T> {
  const CruftFreeRowDetail({this.offered, required this.isOpen, required this.onToggle, required this.build});

  final bool Function(T row)? offered;
  final bool Function(int rowIndex) isOpen;
  final void Function(int rowIndex) onToggle;
  final Widget Function(T row) build;

  /// Whether [row] offers its detail.
  bool offers(T row) => offered?.call(row) ?? true;
}

/// The rows of one table whose detail is open, by their position among the rows shown on one
/// page. The page is named by what decides which rows the table shows ([toggle] and [isOpen]
/// receive it): its arguments, filters, sort and position. Once it changes, every row is
/// closed; a refresh of the same page keeps what is open. Unless [multiple], opening a row
/// closes the one open before.
class CruftFreeOpenRows {
  CruftFreeOpenRows({this.multiple = false});

  final bool multiple;
  List<Object?> _page = const [];
  Set<int> _open = const {};

  /// Whether the [rowIndex]th row of [page] is open.
  bool isOpen(List<Object?> page, int rowIndex) => _samePage(page) && _open.contains(rowIndex);

  /// Opens the [rowIndex]th row of [page], or closes it when it is open.
  void toggle(List<Object?> page, int rowIndex) {
    final open = _samePage(page) ? _open : const <int>{};
    _page = List.unmodifiable(page);
    if (open.contains(rowIndex)) {
      _open = {...open}..remove(rowIndex);
    } else {
      _open = multiple ? {...open, rowIndex} : {rowIndex};
    }
  }

  bool _samePage(List<Object?> page) {
    if (page.length != _page.length) {
      return false;
    }
    for (var index = 0; index < page.length; index++) {
      if (page[index] != _page[index]) {
        return false;
      }
    }
    return true;
  }
}

/// A table's rows under its columns. A table with active filters that shows no
/// row says so (`filteredEmpty`) and offers to clear them (`onClearFilters`).
