  static const double _filterHeadingHeight = 112;
  static const double _filterControlWidth = 200;

  final List<T> rows;
  final List<CruftFreeColumn<T>> columns;
  final String empty;

  /// The empty state's optional description and call to action.
  final String? emptyDescription;
  final List<Widget> emptyActions;
  final List<CruftFreeRowAction<T>> actions;
  final bool Function(T row)? selected;
  final List<CruftFreeRowStyle<T>> rowStyles;
  final PagedBinding<T>? pager;
  final String? filteredEmpty;
  final VoidCallback? onClearFilters;
  final PageSort? clientSort;
  final void Function(String column)? onClientSort;
  final CruftFreeRowDetail<T>? rowDetail;

  /// The heading of [column]: a sortable one cycles its column none, ascending,
  /// descending (from the first page of a paged source); the table shows which
  /// column sorts and how. Its inline filter, while shown, sits under its label.
  DataColumn _heading(CruftFreeColumn<T> column, PagedBinding<T>? paging, CruftFreeInlineFilters? filters) {
    final value = column.sortValue;
    final name = column.filter;
    final Widget label = filters != null && filters.shown && name != null
        ? Column(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(column.label),
              SizedBox(width: _filterControlWidth, child: filters.control(name)),
            ],
          )
        : Text(column.label);
    if (value == null) {
      return DataColumn(label: label, numeric: column.numeric);
    }
    if (paging != null) {
      return DataColumn(label: label, numeric: column.numeric, onSort: (int index, bool ascending) => paging.toggleSort(value));
    }
    final sortLoaded = onClientSort;
    if (sortLoaded == null) {
      throw StateError('Column ${column.label} sorts, but its table neither pages nor sorts its loaded rows.');
    }
    return DataColumn(label: label, numeric: column.numeric, onSort: (int index, bool ascending) => sortLoaded(value));
  }

  /// The last heading of a table with inline filters: the control showing and hiding
  /// them (a `filtersHidden` table's) and, while they are shown, "Clear filters".
  Widget _controlsHeading(CruftFreeInlineFilters? filters) {
    if (filters == null) {
      return const SizedBox.shrink();
    }
    final messages = cruftfreeRuntime.messages;
    return Wrap(
      crossAxisAlignment: WrapCrossAlignment.center,
      children: [
        if (filters.hideable)
          Semantics(
            expanded: filters.shown,
            child: TextButton(onPressed: filters.toggle, child: Text(messages.key(filters.shown ? 'framework.hideFilters' : 'framework.showFilters').text)),
          ),
        if (filters.shown) TextButton(onPressed: filters.clear, child: Text(messages.key('framework.clearFilters').text)),
      ],
    );
  }

  /// [cell] of [row] drawn in each style of [rowStyles] whose condition holds for the row.
  Widget _inRowStyles(BuildContext context, T row, Widget cell) {
    var result = cell;
    for (final rowStyle in rowStyles) {
      if (rowStyle.applies(row)) {
        result = cruftfreeStyled(context, rowStyle.style, result);
      }
    }
    return result;
  }

  /// Whether the detail of [row], the [rowIndex]th row shown, is drawn beneath it: the row
  /// offers it and the reader opened it.
  bool _detailShown(T row, int rowIndex) {
    final detail = rowDetail;
    return detail != null && detail.offers(row) && detail.isOpen(rowIndex);
  }

  /// The first cell of [row]: announced as selected when the table marks a selection, and led
  /// by the row's disclosure control when it offers a detail (an empty slot of the same width
  /// when it does not, so the first column's values line up).
  Widget _firstCell(T row, int rowIndex, Widget cell) {
    final shown = selected == null ? cell : Semantics(selected: selected!(row), child: cell);
    final detail = rowDetail;
    if (detail == null) {
      return shown;
    }
    final Widget toggle = detail.offers(row) ? _detailToggle(detail, rowIndex) : const SizedBox(width: kMinInteractiveDimension);
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        toggle,
        Flexible(child: shown),
      ],
    );
  }

  /// The disclosure control of the [rowIndex]th row: a button announcing whether the row's
  /// detail is expanded, which Enter, Space or a tap toggles.
  Widget _detailToggle(CruftFreeRowDetail<T> detail, int rowIndex) {
    final open = detail.isOpen(rowIndex);
    return Semantics(
      expanded: open,
      child: IconButton(onPressed: () => detail.onToggle(rowIndex), tooltip: cruftfreeRuntime.messages.key(open ? 'framework.hideRowDetail' : 'framework.showRowDetail').text, icon: Icon(open ? Icons.expand_less : Icons.expand_more)),
    );
  }

  @override
  Widget build(BuildContext context) {
    final paging = pager;
    final filters = columns.any((column) => column.filter != null) ? CruftFreeFilterBar.inlineOf(context) : null;
    // With inline filters the table stays shown while they match nothing, and says so under its rows.
    final noMatches = filters == null ? filteredEmpty : null;
    final noMatchesUnder = filters != null && rows.isEmpty ? filteredEmpty : null;
    final controls = actions.isNotEmpty || filters != null;
    final sort = paging?.sort ?? clientSort;
    final sortIndex = sort == null ? -1 : columns.indexWhere((column) => column.sortValue == sort.by);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (rows.isEmpty && noMatches != null)
          Semantics(
            liveRegion: true,
            child: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(noMatches),
                  TextButton(onPressed: onClearFilters, child: Text(cruftfreeRuntime.messages.key('framework.clearFilters').text)),
                ],
              ),
            ),
          )
        else if (rows.isEmpty && noMatchesUnder == null)
          CruftFreeEmptyState(title: empty, description: emptyDescription, icon: Icons.inbox_outlined, actions: emptyActions, card: true)
        else
          CruftFreeTableSurface(
            table: DataTable(
              headingRowHeight: filters != null && filters.shown ? _filterHeadingHeight : null,
              // A detail row is as tall as the detail it draws.
              dataRowMaxHeight: rowDetail != null ? double.infinity : null,
              sortColumnIndex: sortIndex < 0 ? null : sortIndex,
              sortAscending: sort == null || sort.order == SortOrder.asc,
              columns: [
                for (final column in columns) _heading(column, paging, filters),
                if (controls) DataColumn(label: _controlsHeading(filters)),
              ],
              rows: [
                for (final (rowIndex, row) in rows.indexed) ...[
                  DataRow(
                    selected: selected?.call(row) ?? false,
                    cells: [
                      for (final (index, column) in columns.indexed) DataCell(_inRowStyles(context, row, index == 0 ? _firstCell(row, rowIndex, column.cell(row)) : column.cell(row))),
                      if (controls)
                        DataCell(
                          _inRowStyles(
                            context,
                            row,
                            Wrap(
                              children: [
                                for (final action in actions)
                                  if (action.visible) TextButton(onPressed: () => action.onPressed(row), child: Text(action.label)),
                              ],
                            ),
                          ),
                        ),
                    ],
                  ),
                  if (_detailShown(row, rowIndex))
                    DataRow(
                      cells: [
                        DataCell(Semantics(container: true, explicitChildNodes: true, child: rowDetail!.build(row))),
                        for (var index = 1; index < columns.length + (controls ? 1 : 0); index++) const DataCell(SizedBox.shrink()),
                      ],
                    ),
                ],
              ],
            ),
          ),
        if (noMatchesUnder != null) Semantics(liveRegion: true, child: Center(child: Text(noMatchesUnder))),
        if (paging != null) CruftFreePager(binding: paging, minimumPages: 1),
      ],
    );
  }
}

/// How one filter control takes its value.
enum CruftFreeFilterKind { search, select, boolean, date, dateTime, number }

/// One choice of a select filter: the value it holds and its text.
class CruftFreeFilterChoice {
  const CruftFreeFilterChoice(this.value, this.label);

  final String value;
  final String label;
}

/// One filter control: the query parameter it fills, its label and how it
/// takes its value. A select offers `choices` beside the all choice. A `live`
/// control also applies once typing has paused for [cruftfreeLiveInputDelay]. An
/// `inline` control sits under its column's heading rather than in the card.
class CruftFreeFilterField {
  const CruftFreeFilterField({required this.name, required this.label, required this.kind, this.choices = const [], this.live = false, this.inline = false});

  final String name;
  final String label;
  final CruftFreeFilterKind kind;
  final List<CruftFreeFilterChoice> choices;
  final bool live;
  final bool inline;
}

/// What a table reads of the inline filters its [CruftFreeFilterBar] holds: whether they are
/// shown, whether the reader may hide them (`filtersHidden`), each one's control, and
/// the actions of its last heading.
abstract interface class CruftFreeInlineFilters {
  bool get shown;
  bool get hideable;
  Widget control(String name);
  void toggle();
  void clear();
}

/// A table's filters, around the table they filter ([child]): the card above it
/// holds every filter that is not inline. Pressing the search button or Enter in a
/// text field applies what the controls hold, as text keyed by parameter name
/// (a control left unset, empty or not a number sends nothing); clear resets
/// every control and applies none. Changing a `live` control applies them too,
/// once typing has paused; any other apply drops the pause still running.
///
/// With an inline filter, the one clear control ("Clear filters") sits in the
/// table's last heading instead of the card. A [filtersHidden] table's inline
/// filters start hidden; hiding them again clears the values they applied and
/// applies the rest.
class CruftFreeFilterBar extends StatefulWidget {
  const CruftFreeFilterBar({super.key, required this.fields, required this.onApply, required this.child, this.filtersHidden = false});

  final List<CruftFreeFilterField> fields;
  final void Function(Map<String, String> values) onApply;
  final Widget child;
  final bool filtersHidden;

  /// The inline filters of the filter bar around [context].
  static CruftFreeInlineFilters inlineOf(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<_CruftFreeInlineFilterScope>();
    if (scope == null) {
      throw StateError('A table with inline filters is built outside the filter bar holding them.');
    }
    return scope.filters;
  }

  @override
  State<CruftFreeFilterBar> createState() => _CruftFreeFilterBarState();
}

class _CruftFreeInlineFilterScope extends InheritedWidget {
  const _CruftFreeInlineFilterScope({required this.filters, required super.child});

  final CruftFreeInlineFilters filters;

  // The bar rebuilds only when what its filters show changes, so its table follows every rebuild.
  @override
  bool updateShouldNotify(_CruftFreeInlineFilterScope oldWidget) => true;
}

class _CruftFreeFilterBarState extends State<CruftFreeFilterBar> implements CruftFreeInlineFilters {
  static const double _controlWidth = 280;
  static const double _spacing = 16;

  final Map<String, String> _values = {};
  final Map<String, TextEditingController> _controllers = {};
  Map<String, String> _applied = const {};
  int _generation = 0;
  Timer? _liveTimer;
  late bool _shown = !widget.filtersHidden;

  TextEditingController _controller(String name) => _controllers.putIfAbsent(name, TextEditingController.new);

  @override
  bool get shown => _shown;

  @override
  bool get hideable => widget.filtersHidden;

  @override
  Widget control(String name) {
    for (final field in widget.fields) {
      if (field.name == name) {
        return _control(field);
      }
    }
    throw ArgumentError.value(name, 'name', 'names no filter of the table');
  }

  @override
  void dispose() {
    _liveTimer?.cancel();
    for (final controller in _controllers.values) {
      controller.dispose();
    }
    super.dispose();
  }

  void _typed(CruftFreeFilterField field, String text) {
    _values[field.name] = text;
    if (field.live) {
      _liveTimer?.cancel();
      _liveTimer = Timer(cruftfreeLiveInputDelay, _apply);
    }
  }

  void _apply() {
    _liveTimer?.cancel();
    final applied = <String, String>{};
    for (final field in widget.fields) {
      final text = (_values[field.name] ?? '').trim();
      if (text.isEmpty || (field.kind == CruftFreeFilterKind.number && double.tryParse(text)?.isFinite != true)) {
        continue;
      }
      applied[field.name] = text;
    }
    _applied = applied;
    widget.onApply(applied);
  }

  void _clear() {
    _liveTimer?.cancel();
    setState(() {
      _values.clear();
      for (final controller in _controllers.values) {
        controller.clear();
      }
      _generation++;
    });
    _applied = const {};
    widget.onApply(const {});
  }

  @override
  void clear() => _clear();

  @override
  void toggle() {
    if (!_shown) {
      setState(() => _shown = true);
      return;
    }
    _liveTimer?.cancel();
    final inline = {
      for (final field in widget.fields)
        if (field.inline) field.name,
    };
    setState(() {
      for (final name in inline) {
        _values.remove(name);
        _controllers[name]?.clear();
      }
      _generation++;
      _shown = false;
    });
    _applied = {
      for (final entry in _applied.entries)
        if (!inline.contains(entry.key)) entry.key: entry.value,
    };
    widget.onApply(_applied);
  }

  Widget _text(CruftFreeFilterField field) {
    final number = field.kind == CruftFreeFilterKind.number;
    return TextField(
      controller: _controller(field.name),
      decoration: InputDecoration(labelText: field.label, isDense: field.inline, prefixIcon: number || field.inline ? null : const Icon(Icons.search)),
      keyboardType: number ? const TextInputType.numberWithOptions(decimal: true, signed: true) : TextInputType.text,
      textInputAction: TextInputAction.search,
      onChanged: (text) => _typed(field, text),
      onSubmitted: (_) => _apply(),
    );
  }

  Widget _select(CruftFreeFilterField field) {
    final messages = cruftfreeRuntime.messages;
    return CruftFreeSelect<String>(key: ValueKey('${field.name}-$_generation'), label: field.label, value: _values[field.name] ?? '', options: [CruftFreeOption<String>('', messages.key('framework.all').text), for (final choice in field.choices) CruftFreeOption<String>(choice.value, choice.label)], onChanged: (value) => _typed(field, value));
  }

  Widget _temporal(CruftFreeFilterField field) {
    return CruftFreeTemporalInput(key: ValueKey('${field.name}-$_generation'), kind: field.kind == CruftFreeFilterKind.date ? CruftFreeTemporalKind.date : CruftFreeTemporalKind.dateTime, label: field.label, value: _values[field.name], onChanged: (value) => _typed(field, value));
  }

  Widget _control(CruftFreeFilterField field) {
    return switch (field.kind) {
      CruftFreeFilterKind.search || CruftFreeFilterKind.number => _text(field),
      CruftFreeFilterKind.select || CruftFreeFilterKind.boolean => _select(field),
      CruftFreeFilterKind.date || CruftFreeFilterKind.dateTime => _temporal(field),
    };
  }

  /// The card of the filters that are not inline: their controls, Search, and -- with no
  /// inline filter, whose heading holds "Clear filters" instead -- Clear.
  Widget _card(List<CruftFreeFilterField> fields, bool clearsInHeading) {
    final messages = cruftfreeRuntime.messages;
    return Card(
      child: ExpansionTile(
        initiallyExpanded: true,
        title: Text(messages.key('framework.search').text),
        childrenPadding: const EdgeInsets.all(_spacing),
        children: [
          Form(
            child: Wrap(
              spacing: _spacing,
              runSpacing: _spacing,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                for (final field in fields) SizedBox(width: _controlWidth, child: _control(field)),
                FilledButton(onPressed: _apply, child: Text(messages.key('framework.search').text)),
                if (!clearsInHeading) TextButton(onPressed: _clear, child: Text(messages.key('framework.clear').text)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final cardFields = [
      for (final field in widget.fields)
        if (!field.inline) field,
    ];
    return _CruftFreeInlineFilterScope(
      filters: this,
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, mainAxisSize: MainAxisSize.min, children: [if (cardFields.isNotEmpty) _card(cardFields, cardFields.length != widget.fields.length), widget.child]),
    );
  }
}

/// One field of a detail section: its label and its value.
class CruftFreeDetailEntry {
  const CruftFreeDetailEntry({required this.label, required this.value});

  final String label;
  final Widget value;
}

/// A detail section: one object's fields, as label and value pairs, in the [style] of the
/// `table(X) : style(s)` that shows it. Each value follows the style's font; each label is
/// sized from the theme's label role by the same factor (`cruftfreeFontScale`), so the two keep
/// their proportion at any size.
class CruftFreeDetail extends StatelessWidget {
  const CruftFreeDetail({super.key, this.style, required this.entries});

  final CruftFreeStyle? style;
  final List<CruftFreeDetailEntry> entries;

  @override
  Widget build(BuildContext context) {
    final labelStyle = cruftfreeScaledPart(Theme.of(context).textTheme.labelMedium, cruftfreeFontScale(context, style));
    final fields = Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        for (final entry in entries) ...[Text(entry.label, style: labelStyle), entry.value],
      ],
    );
    return cruftfreeStyled(context, style, fields);
  }
}
